import{_ as d,o as e,c as o,a4 as a}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"hi-box 网络性能调优记录","description":"","frontmatter":{"title":"hi-box 网络性能调优记录","date":"2026-07-02T00:00:00.000Z"},"headers":[],"relativePath":"posts/hi-box_网络调优记录.md","filePath":"posts/hi-box_网络调优记录.md"}'),r={name:"posts/hi-box_网络调优记录.md"};function c(h,t,i,n,l,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="hi-box-网络性能调优记录" tabindex="-1">hi-box 网络性能调优记录 <a class="header-anchor" href="#hi-box-网络性能调优记录" aria-label="Permalink to &quot;hi-box 网络性能调优记录&quot;">​</a></h1><blockquote><p>设备: 海思 hi3798mv100 | ARMv7 | 969 MB RAM | 内核 4.4.35_ecoo_81082668 调优日期: 2026-07-02</p></blockquote><hr><h2 id="一、背景" tabindex="-1">一、背景 <a class="header-anchor" href="#一、背景" aria-label="Permalink to &quot;一、背景&quot;">​</a></h2><p>hi-box 运行 mihomo 代理、aria2 下载、openlist 文件服务、easytier VPN、frp 内网穿透等。 需要优化 TCP 网络缓冲以提高代理大包的吞吐性能。</p><h2 id="二、硬件限制" tabindex="-1">二、硬件限制 <a class="header-anchor" href="#二、硬件限制" aria-label="Permalink to &quot;二、硬件限制&quot;">​</a></h2><p>海思芯片网卡<strong>不支持任何硬件卸载</strong>，以下优化不可用：</p><table tabindex="0"><thead><tr><th>功能</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>TSO (TCP Segmentation Offload)</td><td>❌ <code>[fixed]</code> off</td><td>内核手动拆包，CPU 开销大</td></tr><tr><td>GSO</td><td>❌ <code>[fixed]</code> off</td><td>同上</td></tr><tr><td>GRO (Generic Receive Offload)</td><td>❌ <code>[fixed]</code> off</td><td>内核逐个处理收包</td></tr><tr><td>LRO</td><td>❌ <code>[fixed]</code> off</td><td>同上</td></tr><tr><td>Scatter-Gather</td><td>❌ <code>[fixed]</code> off</td><td>无零拷贝支持</td></tr><tr><td>Checksum Offload</td><td>❌ <code>[fixed]</code> off</td><td>内核 CPU 计算校验和</td></tr></tbody></table><p><strong>关键结论</strong>: 瓶颈在 CPU 处理每包能力，不在缓冲区容量。调大 buffer 对硬件瓶颈帮助有限，但仍值得做。</p><p>BBR 拥塞算法和 fq_codel qdisc 同样因定制内核无对应模块/支持而不可用。</p><h2 id="三、调优参数" tabindex="-1">三、调优参数 <a class="header-anchor" href="#三、调优参数" aria-label="Permalink to &quot;三、调优参数&quot;">​</a></h2><p>配置文件: <code>/etc/sysctl.d/99-network-tuning.conf</code></p><h3 id="tcp-缓冲区" tabindex="-1">TCP 缓冲区 <a class="header-anchor" href="#tcp-缓冲区" aria-label="Permalink to &quot;TCP 缓冲区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>调优前</th><th>调优后</th><th>说明</th></tr></thead><tbody><tr><td><code>net.core.rmem_max</code></td><td>4194304 (4 MB)</td><td>8388608 (8 MB)</td><td>接收缓冲区上限</td></tr><tr><td><code>net.core.wmem_max</code></td><td>4194304 (4 MB)</td><td>8388608 (8 MB)</td><td>发送缓冲区上限</td></tr><tr><td><code>net.core.rmem_default</code></td><td>262144 (256 KB)</td><td>524288 (512 KB)</td><td>接收缓冲区默认值</td></tr><tr><td><code>net.core.wmem_default</code></td><td>262144 (256 KB)</td><td>524288 (512 KB)</td><td>发送缓冲区默认值</td></tr><tr><td><code>net.core.optmem_max</code></td><td>10240</td><td>40960</td><td>每 socket 可选缓冲区</td></tr><tr><td><code>net.ipv4.tcp_rmem</code></td><td>4096 131072 4194304</td><td>4096 524288 8388608</td><td>自动调优范围</td></tr><tr><td><code>net.ipv4.tcp_wmem</code></td><td>4096 131072 4194304</td><td>4096 524288 8388608</td><td>自动调优范围</td></tr><tr><td><code>net.ipv4.tcp_mem</code></td><td>5724 7635 11448</td><td>8586 11448 17172</td><td>全局 TCP 内存(pages)</td></tr></tbody></table><h3 id="连接队列" tabindex="-1">连接队列 <a class="header-anchor" href="#连接队列" aria-label="Permalink to &quot;连接队列&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>调优前</th><th>调优后</th><th>说明</th></tr></thead><tbody><tr><td><code>net.core.somaxconn</code></td><td>512</td><td>1024</td><td>listen 队列上限</td></tr><tr><td><code>net.core.netdev_max_backlog</code></td><td>65536</td><td>65536</td><td>已够，保持</td></tr><tr><td><code>net.ipv4.tcp_max_syn_backlog</code></td><td>512</td><td>2048</td><td>SYN 队列上限</td></tr></tbody></table><h3 id="低延迟优化" tabindex="-1">低延迟优化 <a class="header-anchor" href="#低延迟优化" aria-label="Permalink to &quot;低延迟优化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>调优前</th><th>调优后</th><th>说明</th></tr></thead><tbody><tr><td><code>net.core.busy_read</code></td><td>0</td><td>50</td><td>busy polling 50μs，降低小包延迟</td></tr><tr><td><code>net.ipv4.tcp_low_latency</code></td><td>0</td><td>1</td><td>减少缓冲延迟</td></tr></tbody></table><h3 id="tcp-特性" tabindex="-1">TCP 特性 <a class="header-anchor" href="#tcp-特性" aria-label="Permalink to &quot;TCP 特性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>调优前</th><th>调优后</th><th>说明</th></tr></thead><tbody><tr><td><code>net.ipv4.tcp_fastopen</code></td><td>0</td><td>3</td><td>TCP Fast Open 客户端+服务端</td></tr><tr><td><code>net.ipv4.tcp_mtu_probing</code></td><td>0</td><td>1</td><td>自动探测最优 MTU</td></tr><tr><td><code>net.ipv4.tcp_ecn</code></td><td>0</td><td>2</td><td>ECN 显式拥塞通知</td></tr><tr><td><code>net.ipv4.tcp_timestamps</code></td><td>1</td><td>1</td><td>保持</td></tr><tr><td><code>net.ipv4.tcp_sack</code></td><td>1</td><td>1</td><td>保持</td></tr><tr><td><code>net.ipv4.tcp_retries2</code></td><td>15</td><td>8</td><td>降低重试次数，快速失败</td></tr><tr><td><code>net.ipv4.tcp_orphan_retries</code></td><td>3</td><td>0</td><td>无连接关联的快速失败</td></tr><tr><td><code>net.ipv4.tcp_no_metrics_save</code></td><td>0</td><td>1</td><td>断开连接不清零重传历史</td></tr></tbody></table><h3 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>调优前</th><th>调优后</th><th>说明</th></tr></thead><tbody><tr><td><code>vm.min_free_kbytes</code></td><td>2808</td><td>8192</td><td>预留更多空闲内存防 OOM</td></tr><tr><td><code>vm.swappiness</code></td><td>60</td><td>10</td><td>无 swap，降低不必要判断</td></tr><tr><td><code>vm.vfs_cache_pressure</code></td><td>100</td><td>50</td><td>降低 dentry/inode 回收压力，NFS 友好</td></tr></tbody></table><h2 id="四、效果预期" tabindex="-1">四、效果预期 <a class="header-anchor" href="#四、效果预期" aria-label="Permalink to &quot;四、效果预期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>预期提升</th></tr></thead><tbody><tr><td>代理高延迟链路吞吐</td><td>+20~40%</td></tr><tr><td>小包延迟</td><td>降低 (busy_read + low_latency)</td></tr><tr><td>突发连接稳定性</td><td>提升 (队列翻倍)</td></tr><tr><td>MTU 自适应</td><td>避免分片丢包</td></tr></tbody></table><h2 id="五、持久化" tabindex="-1">五、持久化 <a class="header-anchor" href="#五、持久化" aria-label="Permalink to &quot;五、持久化&quot;">​</a></h2><p>配置写入 <code>/etc/sysctl.d/99-network-tuning.conf</code>，重启后自动加载。 手动生效命令: <code>sysctl --system</code></p><h2 id="六、备注" tabindex="-1">六、备注 <a class="header-anchor" href="#六、备注" aria-label="Permalink to &quot;六、备注&quot;">​</a></h2><ul><li>969MB 内存 × 8MB buffer × 数百并发连接 = ~2GB 潜在峰值，实测正常场景远低于此</li><li>BBR / fq_codel 需升级内核才能使用，当前定制 4.4 内核不支持</li><li>NFS 随机端口可固定：修改 <code>/etc/default/nfs-kernel-server</code> 中 <code>RPCMOUNTDOPTS</code> 加入 <code>--port 4001</code></li></ul>',28)])])}const _=d(r,[["render",c]]);export{p as __pageData,_ as default};
